import { Integrations } from "../components/integrations";

export default function page() {
	return (
		<div className="min-h-screen place-content-center">
			<Integrations />
		</div>
	);
}

import type { ElementType, SVGProps } from "react";
import {
	Cursor as CursorLogo,
	GoogleGmail as GmailLogo,
	Neon as NeonLogo,
	Notion as NotionLogo,
	PlanetScale as PlanetscaleLogo,
	Vercel as VercelLogo,
} from "love-ui/logos";

import { cn } from "@/lib/utils";
import { DecorIcon } from "./decor-icon";

type LogoComponent = ElementType<SVGProps<SVGSVGElement>>;

type Integration = {
	Component: LogoComponent;
	name: string;
	description: string;
	isInvertable?: boolean;
	logoClassName?: string;
	icon?: React.ReactNode;
};

const data: Integration[] = [
	{
		Component: VercelLogo,
		name: "Vercel",
		description:
			"Deploy LoveUI block previews, docs, and production product pages.",
		isInvertable: true,
	},
	{
		Component: CursorLogo,
		name: "Cursor",
		description:
			"Use LoveUI Skills to give AI agents concrete interface guidance.",
		isInvertable: true,
		icon: <DecorIcon position="bottom-left" />,
	},
	{
		Component: NeonLogo,
		name: "Neon",
		description:
			"Connect polished LoveUI surfaces to serverless Postgres and application data.",
	},
	{
		Component: PlanetscaleLogo,
		name: "PlanetScale",
		description: "Back product screens with schema changes your team can review.",
		isInvertable: true,
	},
	{
		Component: NotionLogo,
		name: "Notion",
		description: "Track component decisions, block adoption, and design system notes.",
		logoClassName: "text-black",
	},
	{
		Component: GmailLogo,
		name: "Gmail",
		description: "Send product notifications from interfaces built with LoveUI forms.",
		icon: <DecorIcon position="top-left" />,
	},
];

export function Integrations() {
	return (
		<div className="relative mx-auto max-w-5xl border">
			<div className="grid grid-cols-2 gap-px bg-border md:grid-cols-3">
				{data.map((item) => (
					<IntegrationCard integration={item} key={item.name}>
						{item.icon}
					</IntegrationCard>
				))}
			</div>
			<DecorIcon position="top-left" />
			<DecorIcon position="top-right" />
			<DecorIcon position="bottom-left" />
			<DecorIcon position="bottom-right" />
		</div>
	);
}

function IntegrationCard({
	integration,
	className,
	children,
	...props
}: React.ComponentProps<"div"> & { integration: Integration }) {
	return (
		<div
			className={cn(
				"relative flex flex-col items-start gap-4 bg-background p-4 text-start md:p-6 md:even:bg-background/75",
				className
			)}
			{...props}
		>
			<LogoAsset
				className="pointer-events-none size-9 shrink-0 select-none object-contain"
				integration={integration}
			/>
			<div className="space-y-1">
				<h3 className="font-semibold">{integration.name}</h3>
				<p className="text-muted-foreground text-xs md:text-sm">
					{integration.description}
				</p>
			</div>
			{children}
		</div>
	);
}

function LogoAsset({
	integration,
	className,
}: {
	integration: Integration;
	className: string;
}) {
	const Component = integration.Component;

	return (
		<Component
			aria-label={integration.name}
			className={cn(
				className,
				integration.isInvertable && "text-foreground",
				integration.logoClassName
			)}
			role="img"
		/>
	);
}

import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";

const DecorIconVariants = cva(
    "pointer-events-none absolute z-1 size-4 shrink-0 stroke-1 stroke-muted-foreground transition-transform",
    {
        variants: {
            position: {
                // We also rotate the SVG inside the variant so the bracket always points inward
                "top-left":
                    "top-0 left-0 -translate-x-1/2 -translate-y-1/2",
                "top-right":
                    "top-0 right-0 translate-x-1/2 -translate-y-1/2 rotate-90",
                "bottom-right":
                    "right-0 bottom-0 translate-x-1/2 translate-y-1/2 rotate-180",
                "bottom-left":
                    "bottom-0 left-0 -translate-x-1/2 translate-y-1/2 -rotate-90",
            },
        },
        defaultVariants: {
            position: "top-left",
        },
    }
);

type DecorIconProps = React.ComponentProps<"svg"> &
    VariantProps<typeof DecorIconVariants> & {
        variant?: "bracket" | "dot" | "diagonal";
    };

export function DecorIcon({ position, variant = "bracket", className, ...props }: DecorIconProps) {
    return (
        <svg
            aria-hidden="true"
            className={cn(DecorIconVariants({ position, className }))}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
            xmlns="http://www.w3.org/2000/svg"
            {...props}
        >
            {/* OPTION 1: Corner Bracket (Default) */}
            {variant === "bracket" && (
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 4H4v8" />
            )}

            {/* OPTION 2: Minimalist Dot (Change fill to currentColor in class if using this) */}
            {variant === "dot" && (
                <circle cx="12" cy="12" r="3" fill="currentColor" />
            )}

            {/* OPTION 3: Diagonal Accent Line */}
            {variant === "diagonal" && (
                <path strokeLinecap="round" d="M4 20L20 4" />
            )}
        </svg>
    );
}
